import React, { useState } from "react";
import { Link } from "react-router-dom";

function Sidebar() {
  const [open, setOpen] = useState(false);

  return (
    <>
      {/* Toggle Button */}
      <button
        onClick={() => setOpen(!open)}
        style={styles.toggleBtn}
      >
        ☰
      </button>

      {/* Sidebar */}
      <div
        style={{
          ...styles.sidebar,
          left: open ? "0" : "-250px"
        }}
      >
        <h2>🛡 SOC Panel</h2>

        <ul style={styles.menu}>
          <li>
            <Link
              to="/dashboard"
              style={styles.link}
              onClick={() => setOpen(false)}
            >
              Dashboard
            </Link>
          </li>

          <li>
            <Link
              to="/threats"
              style={styles.link}
              onClick={() => setOpen(false)}
            >
              Threats
            </Link>
          </li>

          <li>
            <Link
              to="/incidents"
              style={styles.link}
              onClick={() => setOpen(false)}
            >
              Incidents
            </Link>
          </li>

          <li>
            <Link
              to="/packets"
              style={styles.link}
              onClick={() => setOpen(false)}
            >
              Packets
            </Link>
          </li>

          <li>
            <Link
              to="/settings"
              style={styles.link}
              onClick={() => setOpen(false)}
            >
              Settings
            </Link>
          </li>

          <li>
            <Link
              to="/login"
              style={styles.logout}
              onClick={() => {
                localStorage.removeItem("access_token");
                setOpen(false);
              }}
            >
              Logout
            </Link>
          </li>
        </ul>
      </div>
    </>
  );
}

const styles = {
  toggleBtn: {
    position: "fixed",
    top: "15px",
    left: "15px",
    zIndex: 1000,
    background: "#111827",
    color: "white",
    border: "none",
    padding: "10px 14px",
    borderRadius: "8px",
    cursor: "pointer",
    fontSize: "22px"
  },

  sidebar: {
    position: "fixed",
    top: 0,
    left: "-250px",
    width: "240px",
    height: "100vh",
    background: "#111827",
    padding: "20px",
    transition: "0.3s ease",
    zIndex: 999
  },

  menu: {
    listStyle: "none",
    padding: 0,
    marginTop: "30px",
    lineHeight: "45px",
    fontSize: "18px"
  },

  link: {
    color: "white",
    textDecoration: "none",
    display: "block"
  },

  logout: {
    color: "#ff5555",
    textDecoration: "none",
    display: "block",
    marginTop: "30px"
  }
};

export default Sidebar;
